class TrialCounter:
    def __init__(self, db_path: str):
        self.db_path = db_path
        self._init_db()

    def _init_db(self):
        with sqlite3.connect(self.db_path) as conn:
            conn.execute("""
                CREATE TABLE IF NOT EXISTS trials (
                    trial_id TEXT PRIMARY KEY,
                    dataset_id TEXT NOT NULL,
                    strategy TEXT,
                    params TEXT,
                    search_id TEXT,
                    researcher TEXT,
                    start_time REAL NOT NULL,
                    sharpe REAL
                )
            """)
            # R7: Deleting a row MUST fail
            conn.execute("CREATE TRIGGER IF NOT EXISTS prevent_delete BEFORE DELETE ON trials BEGIN SELECT RAISE(FAIL, 'Deletions are forbidden'); END;")
            # R7: Changing dataset_id MUST fail
            conn.execute("CREATE TRIGGER IF NOT EXISTS prevent_dataset_update BEFORE UPDATE OF dataset_id ON trials BEGIN SELECT RAISE(FAIL, 'dataset_id is immutable'); END;")
            # R7: Rewriting a recorded sharpe MUST fail
            conn.execute("CREATE TRIGGER IF NOT EXISTS prevent_sharpe_update BEFORE UPDATE OF sharpe ON trials WHEN OLD.sharpe IS NOT NULL BEGIN SELECT RAISE(FAIL, 'sharpe is immutable once recorded'); END;")
            conn.commit()

    def start_trial(self, dataset_id: str, strategy: str = None, params: dict = None, search_id: str = None, researcher: str = None) -> str:
        if not dataset_id or not dataset_id.strip():
            raise ValueError("dataset_id is required and cannot be empty or whitespace-only")

        if params is not None and not isinstance(params, dict):
            raise TypeError("params must be a dict")

        trial_id = str(uuid.uuid4())
        params_json = json.dumps(params) if params is not None else None
        start_time = time.time()

        with sqlite3.connect(self.db_path) as conn:
            conn.execute(
                "INSERT INTO trials (trial_id, dataset_id, strategy, params, search_id, researcher, start_time, sharpe) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                (trial_id, dataset_id, strategy, params_json, search_id, researcher, start_time, None)
            )
            conn.commit()
        return trial_id

    def record_outcome(self, trial_id: str, sharpe: float, **kwargs):
        if not isinstance(trial_id, str):
            raise TypeError("trial_id must be a string")

        if not isinstance(sharpe, (int, float)):
            raise TypeError("sharpe must be numeric")

        if not math.isfinite(sharpe):
            raise ValueError("sharpe must be finite")

        with sqlite3.connect(self.db_path) as conn:
            # Check if trial exists and if it already has an outcome
            cursor = conn.execute("SELECT sharpe FROM trials WHERE trial_id = ?", (trial_id,))
            row = cursor.fetchone()

            if row is None:
                raise ValueError(f"Unknown trial_id: {trial_id}")

            if row[0] is not None:
                raise ValueError(f"Trial {trial_id} already has an outcome")

            conn.execute("UPDATE trials SET sharpe = ? WHERE trial_id = ?", (float(sharpe), trial_id))
            conn.commit()

    def trial_count(self, dataset_id: str) -> int:
        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.execute("SELECT COUNT(*) FROM trials WHERE dataset_id = ?", (dataset_id,))
            return cursor.fetchone()[0]

    def sharpe_variance(self, dataset_id: str) -> float | None:
        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.execute("SELECT sharpe FROM trials WHERE dataset_id = ? AND sharpe IS NOT NULL", (dataset_id,))
            sharpes = [row[0] for row in cursor.fetchall()]

        n = len(sharpes)
        if n < 2:
            return None

        mean = sum(sharpes) / n
        variance = sum((x - mean) ** 2 for x in sharpes) / (n - 1)
        return variance

    def deflation_inputs(self, dataset_id: str) -> dict:
        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.execute("SELECT COUNT(*) FROM trials WHERE dataset_id = ?", (dataset_id,))
            n_trials = cursor.fetchone()[0]

            cursor = conn.execute("SELECT COUNT(*) FROM trials WHERE dataset_id = ? AND sharpe IS NOT NULL", (dataset_id,))
            trials_with_outcome = cursor.fetchone()[0]

            trials_without_outcome = n_trials - trials_with_outcome

