        return {
            "n_trials": n_trials,
            "var_trials": var_trials,
            "trials_with_outcome": trials_with_outcome,
            "trials_without_outcome": trials_without_outcome
        }

    def search_trial_count(self, search_id: str) -> int:
        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.execute("SELECT COUNT(*) FROM trials WHERE search_id = ?", (search_id,))
            return cursor.fetchone()[0]

    def trials(self, dataset_id: str):
        """Returns records ordered by the time the trial was started, oldest first."""
        with sqlite3.connect(self.db_path) as conn:
