import statistics

def cornish_fisher_quantile(confidence: float, skewness: float, kurtosis: float) -> float:
    """
    Calculates the Cornish-Fisher adjusted quantile for a given tail probability.

    Formula used (Zangari, 1996):
    w_p = z_p + (1/6)*(z_p^2 - 1)*S + (1/24)*(z_p^3 - 3*z_p)*K - (1/36)*(2*z_p^3 - 5*z_p)*S^2

    Where:
    - z_p is the standard normal quantile (inv_cdf(p))
    - S is the skewness
    - K is the excess kurtosis (normal = 0)

    Source: Zangari, R. (1996). "A note on the Cornish-Fisher expansion".

    Args:
        confidence: The tail probability (e.g., 0.05 for 95% confidence).
        skewness: The skewness of the distribution.
        kurtosis: The excess kurtosis of the distribution (normal = 0).

    Returns:
        The adjusted quantile as a float.

    Raises:
        ValueError: If confidence is not in (0, 1) or if inputs are non-finite.
        TypeError: If any input is not a numeric type.
    """
    if not isinstance(confidence, (int, float)):
        raise TypeError("confidence must be a numeric type")
    if not isinstance(skewness, (int, float)):
        raise TypeError("skewness must be a numeric type")
    if not isinstance(kurtosis, (int, float)):
        raise TypeError("kurtosis must be a numeric type")

    if not (0 < confidence < 1):
        raise ValueError("confidence must be in the range (0, 1)")

    import math
    if not all(math.isfinite(x) for x in [confidence, skewness, kurtosis]):
        raise ValueError("All inputs must be finite numbers")

    z_p = statistics.NormalDist().inv_cdf(confidence)

    term1 = (1/6) * (z_p**2 - 1) * skewness
    term2 = (1/24) * (z_p**3 - 3*z_p) * kurtosis
    term3 = (1/36) * (2*z_p**3 - 5*z_p) * (skewness**2)

    return z_p + term1 + term2 - term3

def modified_var(mean: float, volatility: float, confidence: float, skewness: float, kurtosis: float) -> float:
    """
    Calculates the Cornish-Fisher modified Value-at-Risk (VaR).

    VaR is returned as a positive number representing a loss.

    Args:
        mean: The mean return of the distribution.
        volatility: The standard deviation of the distribution.
        confidence: The tail probability (e.g., 0.05 for 95% confidence).
        skewness: The skewness of the distribution.
        kurtosis: The excess kurtosis of the distribution (normal = 0).

    Returns:
        The VaR as a positive float representing a loss.

    Raises:
        ValueError: If volatility is negative or if inputs are non-finite.
        TypeError: If any input is not a numeric type.
    """
    if not isinstance(mean, (int, float)):
        raise TypeError("mean must be a numeric type")
    if not isinstance(volatility, (int, float)):
        raise TypeError("volatility must be a numeric type")
    if not isinstance(confidence, (int, float)):
        raise TypeError("confidence must be a numeric type")
    if not isinstance(skewness, (int, float)):
        raise TypeError("skewness must be a numeric type")
    if not isinstance(kurtosis, (int, float)):
        raise TypeError("kurtosis must be a numeric type")

    import math
    if not all(math.isfinite(x) for x in [mean, volatility, confidence, skewness, kurtosis]):
        raise ValueError("All inputs must be finite numbers")

    if volatility < 0:
        raise ValueError("volatility cannot be negative")

    # The quantile of the return distribution
    w_p = cornish_fisher_quantile(confidence, skewness, kurtosis)

    # Return quantile = mean + volatility * w_p
    # VaR = -Return quantile
    return -(mean + volatility * w_p)

