import numpy as np

def assert_no_leakage(train_idx, test_idx, label_start, label_end):
    """
    Raises ValueError if any training label overlaps the test window.

    The test window is defined as [min(label_start[test_idx]), max(label_end[test_idx])].
    An overlap occurs if [label_start[i], label_end[i]] intersects the test window.
    """
    if len(test_idx) == 0:
        return None

    test_window_start = np.min(label_start[test_idx])
    test_window_end = np.max(label_end[test_idx])

    # Overlap condition: start1 <= end2 AND end1 >= start2
    # Here: label_start[i] <= test_window_end AND label_end[i] >= test_window_start
    overlaps = (label_start[train_idx] <= test_window_end) & (label_end[train_idx] >= test_window_start)

    if np.any(overlaps):
        leaking_indices = train_idx[overlaps]
        raise ValueError(f"Leakage detected! Training indices {leaking_indices} overlap the test window [{test_window_start}, {test_window_end}].")

    return None

