        label_start = np.asarray(label_start)
        label_end = np.asarray(label_end)
        n_observations = len(label_start)

        # Validations
        if len(label_start) != len(label_end):
            raise ValueError("label_start and label_end must have the same length")
        if not np.all(np.diff(label_start) >= 0):
            raise ValueError("label_start must be sorted ascending")
        if not np.all(label_end >= label_start):
            raise ValueError("label_end[i] must be >= label_start[i]")

        # Create base contiguous folds
        indices = np.arange(n_observations)
        # Use array_split to get n_splits contiguous chunks
        test_folds = np.array_split(indices, self.n_splits)

        embargo_size = int(self.embargo_pct * n_observations)

        for test_idx in test_folds:
            if len(test_idx) == 0:
                # This shouldn't happen with array_split unless n_splits > n_observations
                continue

            test_window_start = np.min(label_start[test_idx])
            test_window_end = np.max(label_end[test_idx])

